# Let me verify with a cleaner BFS that properly tracks shortest path distances
from collections import deque

def bfs_depth_n(graph, start, target_depth):
    """Find all nodes at exactly target_depth from start using BFS."""
    queue = deque([start])
    distances = {start: 0}
    result = set()

    while queue:
        node = queue.popleft()
        current_dist = distances[node]

        if current_dist >= target_depth:
            continue

        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in distances:
                    distances[neighbor] = current_dist + 1
                    if current_dist + 1 == target_depth:
                        result.add(neighbor)
                    queue.append(neighbor)

    return result, distances

depth_2, all_distances = bfs_depth_n(graph, "eccbc87e4b", 2)

print("All distances from eccbc87e4b:")
for node, dist in sorted(all_distances.items()):
    print(f"  {node}: {dist}")

print(f"\nNodes at exactly depth 2: {sorted(depth_2)}")

# Verify by checking what nodes are at depth 1
depth_1 = {n for n, d in all_distances.items() if d == 1}
print(f"Nodes at exactly depth 1: {sorted(depth_1)}")
```

